<script setup>
import HealthMealJournal from '../../components/HealthMealJournal.vue'
import { isMockMode } from '../../services/config.js'
import AppNavBar from '../../components/AppNavBar.vue'
import { computed,ref } from 'vue'
import { onShow } from '@dcloudio/uni-app'
import { localDate } from '../../utils/meal-state.js'
import { backHome,getProfile,getRecords } from '../../utils/profile.js'
import { intakeSummary } from '../../utils/scan-portions.js'
const profile=ref(getProfile()),records=ref(getRecords()),scope=ref('all'),date=ref(localDate())
onShow(()=>{profile.value=getProfile();records.value=getRecords()})
const visible=computed(()=>records.value.filter(r=>(r.createdAt?localDate(new Date(r.createdAt)):String(r.date||'').slice(0,10))===date.value).filter(r=>scope.value==='all'||String(r.memberId)===String(scope.value)||r.memberIds?.map(String).includes(String(scope.value))))
function scopedIntake(record){return scope.value==='all'?null:record.memberIntake?.find(item=>String(item.memberId)===String(scope.value))}
function summary(record){const intake=scopedIntake(record);return {dishes:intake?intake.dishes||[]:record.dishes||[],portion:intake?intakeSummary(intake):intakeSummary({dishes:record.dishes||[],portion:record.portion||'粗略份量',grams:record.grams})}}
function detail(record){uni.navigateTo({url:'/pages/records/detail?id='+encodeURIComponent(record.id)})}
</script>
<template><view v-if="!isMockMode" class="screen journal-screen"><AppNavBar title="饮食记录"><template #left><button class="icon-button" @click="backHome">‹</button></template></AppNavBar><HealthMealJournal/></view><view v-else class="screen journal-mock"><AppNavBar title="饮食记录"><template #left><button class="icon-button" @click="backHome">‹</button></template></AppNavBar><view class="hero"><text class="eyebrow">ORIGINAL RECORDS</text><text class="display-title">今天真正吃了什么</text><text>这里保留原始记录与更正版本，不代替 AI 反馈页。</text></view><scroll-view class="scope-tabs" scroll-x><view class="scope-row"><button :class="{active:scope==='all'}" @click="scope='all'">全家</button><button v-for="m in profile.members" :key="m.id" :class="{active:scope===m.id}" @click="scope=m.id">{{m.name}}</button></view></scroll-view><view class="date-card card"><picker mode="date" :value="date" @change="date=$event.detail.value"><text>{{date}} ›</text></picker><text>按北京时间归档</text></view><view class="meal-list"><view v-for="meal in ['早餐','午餐','晚餐']" :key="meal" class="meal-card card"><view class="meal-head"><text>{{meal}}</text><text>{{visible.filter(r=>r.meal===meal).length?'已记录':'未记录'}}</text></view><button v-for="r in visible.filter(item=>item.meal===meal)" :key="r.id" @click="detail(r)"><view class="photo-mark">{{r.photo?'图':'记'}}</view><view><text>{{summary(r).dishes.join('、')||'暂未确认菜品'}}</text><text>{{scopedIntake(r)?.memberName||(r.memberNames?.join('、')||r.memberName)}} · {{summary(r).portion}}</text></view><text>›</text></button><text v-if="!visible.some(r=>r.meal===meal)" class="missing">未记录不代表没有进食，不会被当作 0 摄入。</text></view></view></view></template>
<style>.journal-screen{padding-left:28rpx;padding-right:28rpx;padding-bottom:calc(env(safe-area-inset-bottom) + 14rpx);background:#f5f6fa;background-image:radial-gradient(ellipse at 0% 0%,rgba(125,174,255,.44),transparent 70%),radial-gradient(ellipse at 100% 0%,rgba(206,178,245,.38),transparent 76%);background-size:100% 410rpx;background-repeat:no-repeat}.journal-screen .icon-button{min-width:44px;min-height:44px}.journal-mock .hero{display:flex;flex-direction:column;gap:12rpx;margin:43rpx 0 24rpx}.journal-mock .hero .display-title{font-size:44rpx}.journal-mock .hero>text:last-child{color:#6e6e78;font-size:25rpx;line-height:1.6}.journal-mock .scope-tabs{white-space:nowrap}.journal-mock .scope-tabs .scope-row{display:inline-flex;gap:10rpx}.journal-mock .scope-tabs button{padding:13rpx 23rpx;border-radius:17rpx;background:#f0f1f4;color:#6e6e78;font-size:25rpx}.journal-mock .scope-tabs button.active{background:#292a2e;color:#fff}.journal-mock .date-card{display:flex;justify-content:space-between;margin-top:18rpx;padding:20rpx}.journal-mock .date-card text:first-child{font-size:25rpx;font-weight:500}.journal-mock .date-card text:last-child{color:#6e6e78;font-size:25rpx}.journal-mock .meal-list{display:flex;flex-direction:column;gap:14rpx;margin-top:18rpx}.journal-mock .meal-card{padding:22rpx}.journal-mock .meal-head{display:flex;justify-content:space-between;margin-bottom:12rpx}.journal-mock .meal-head text:first-child{font-size:26rpx;font-weight:500}.journal-mock .meal-head text:last-child{color:#292a2e;font-size:25rpx;font-weight:500}.journal-mock .meal-card button{width:100%;display:flex;align-items:center;gap:14rpx;padding:14rpx 0;text-align:left}.journal-mock .photo-mark{width:58rpx;height:58rpx;display:flex;align-items:center;justify-content:center;border-radius:18rpx;background:#f5f5f7;color:#292a2e;font-weight:500}.journal-mock .meal-card button>view:nth-child(2){flex:1;display:flex;flex-direction:column;gap:6rpx}.journal-mock .meal-card button>view:nth-child(2) text:first-child{font-size:25rpx;font-weight:500}.journal-mock .meal-card button>view:nth-child(2) text:last-child,.journal-mock .missing{color:#6e6e78;font-size:25rpx;line-height:1.5}.journal-mock .missing{display:block;padding:12rpx 0}</style>
